'use strict';
// 5.0 runtime: bounded reusable textures and a display-independent simulation clock.
const meshLayouts=new Map(),meshTextures=new Map(),textureArtIds=new WeakMap();
let nextTextureArtId=1,textureBytes=0,simulationBatch=false,lastHudPaint=-Infinity;
const MAX_FRAME_CATCHUP=.1,TEXTURE_CACHE_LIMIT=24*1024*1024;
function meshTexture(art,crop,w,h){if(typeof OffscreenCanvas==='undefined')return null;let id=textureArtIds.get(art);if(!id){id=nextTextureArtId++;textureArtIds.set(art,id);}const tw=Math.ceil(w*2),th=Math.ceil(h*2),key=id+':'+crop.join(',')+':'+tw+':'+th;let entry=meshTextures.get(key);if(entry){meshTextures.delete(key);meshTextures.set(key,entry);return entry.surface.width?entry.surface:null;}const bytes=tw*th*4;if(bytes>TEXTURE_CACHE_LIMIT)return null;while(textureBytes+bytes>TEXTURE_CACHE_LIMIT&&meshTextures.size){const oldest=meshTextures.keys().next().value;textureBytes-=meshTextures.get(oldest).bytes;meshTextures.get(oldest).surface.close?.();meshTextures.delete(oldest);}const surface=new OffscreenCanvas(tw,th),paint=surface.getContext('2d');paint.imageSmoothingEnabled=true;paint.imageSmoothingQuality='high';paint.drawImage(art,crop[0]*art.naturalWidth,crop[1]*art.naturalHeight,crop[2]*art.naturalWidth,crop[3]*art.naturalHeight,0,0,tw,th);const image=surface.transferToImageBitmap?surface.transferToImageBitmap():surface;meshTextures.set(key,{surface:image,bytes});textureBytes+=bytes;return image.width?image:null;}
function meshLayout(w,h,cols,rows){const key=[w,h,cols,rows].join(':');let m=meshLayouts.get(key);if(m)return m;const vertices=[],triangles=[];for(let j=0;j<=rows;j++)for(let i=0;i<=cols;i++)vertices.push({u:i/cols,v:j/rows,sx:i/cols*w,sy:j/rows*h,x:0,y:0});function add(ia,ib,ic){const a=vertices[ia],b=vertices[ib],c=vertices[ic],den=a.sx*(b.sy-c.sy)+b.sx*(c.sy-a.sy)+c.sx*(a.sy-b.sy);triangles.push({ia,ib,ic,ax:(b.sy-c.sy)/den,bx:(c.sy-a.sy)/den,cx:(a.sy-b.sy)/den,ay:(c.sx-b.sx)/den,by:(a.sx-c.sx)/den,cy:(b.sx-a.sx)/den});}for(let j=0;j<rows;j++)for(let i=0;i<cols;i++){const k=j*(cols+1)+i;add(k,k+1,k+cols+1);add(k+1,k+cols+2,k+cols+1);}m={vertices,triangles};if(meshLayouts.size>=48)meshLayouts.delete(meshLayouts.keys().next().value);meshLayouts.set(key,m);return m;}
function advanceSimulation(seconds){const elapsed=Math.max(0,Math.min(seconds,MAX_FRAME_CATCHUP));if(!elapsed)return;const steps=Math.max(1,Math.ceil(elapsed/(1/60)-1e-8)),dt=elapsed/steps;simulationBatch=true;try{for(let i=0;i<steps;i++)update(dt);}finally{simulationBatch=false;}}

function setHtmlIfChanged(el,html){if(el.innerHTML!==html)el.innerHTML=html;}

function setTextIfChanged(el,text){if(el.textContent!==text)el.textContent=text;}
